BEGIN TRANSACTION;
CREATE TABLE channel_week(week_start TEXT NOT NULL,channel TEXT NOT NULL,spend REAL NOT NULL,platform_purchases INTEGER NOT NULL,platform_revenue REAL NOT NULL,PRIMARY KEY(week_start,channel));
CREATE TABLE customers(customer_id TEXT PRIMARY KEY,first_paid_order_id TEXT NOT NULL);
CREATE TABLE funnel_events(event_id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(session_id),event_type TEXT NOT NULL,occurred_at TEXT NOT NULL);
CREATE TABLE orders(order_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(customer_id),week_start TEXT NOT NULL,last_click_channel TEXT NOT NULL,gross_revenue REAL NOT NULL,session_id TEXT NOT NULL REFERENCES sessions(session_id),paid_at TEXT NOT NULL);
CREATE TABLE refunds(refund_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(order_id),refund_amount REAL NOT NULL);
CREATE TABLE sessions(session_id TEXT PRIMARY KEY,started_at TEXT NOT NULL,week_start TEXT NOT NULL,channel TEXT NOT NULL,device_type TEXT NOT NULL);
CREATE INDEX events_session_type_time ON funnel_events(session_id,event_type,occurred_at);
CREATE INDEX orders_session_time ON orders(session_id,paid_at);
CREATE INDEX refunds_order ON refunds(order_id);
COMMIT;
